/** Checks meaning search again (Settings' Refresh): starts Ollama when nothing answers on this machine, downloads the model when it is missing. Result: the `embeddings` item */
export type EmbeddingsCheckParams = {

};

/** Merges the branch of an agent's worktree into what its project has checked out (a merge commit). Refused while it has changes not committed; a conflict is undone. Result: {said} */
export type WorktreeMergeParams = {
  /** the agent's id */
  agent: string;
};

/** Closes an agent and removes its worktree, and its branch once merged (an unmerged branch is kept). Refused while it works or has changes not committed. Result: {said} */
export type WorktreeRemoveParams = {
  /** the agent's id */
  agent: string;
};

/** Renames a project. Result: {} */
export type RenameProjectParams = {
  /** the project's id (its folder) */
  project: string;
  /** its new name (empty: the folder's) */
  name: string;
};

/** Folds a project in the sidebar, or unfolds it (every UI's). Result: {} */
export type SetCollapsedParams = {
  /** the project's id (its folder) */
  project: string;
  /** its agents hidden (true) or shown */
  collapsed: boolean;
};

/** Takes a project out of the sidebar, closing its agents (they can be reopened). A conflict while any of them works. Result: {} */
export type RemoveProjectParams = {
  /** the project's id (its folder) */
  project: string;
};

/** Closes an agent (its conversation resource ends: gone). Result: {} */
export type CloseAgentParams = {
  /** the agent's id */
  agent: string;
};

/** A new job in the project's tray. Result: {job} */
export type RunJobParams = {
  /** the project's id (its folder) */
  project: string;
  /** a shell command */
  command: string;
  /** the job's name (else its program's) */
  name?: string;
};

/** Stops a job. Result: {} */
export type StopJobParams = {
  /** the job's id */
  job: string;
};

/** A job's output as text (to copy). Result: {text} */
export type JobTextParams = {
  /** the job's id */
  job: string;
  /** its last lines (2000; 20000 tops) */
  lines?: number;
};

/** Takes a job that has exited out of its tray (a conflict while it runs). Result: {} */
export type RemoveJobParams = {
  /** an exited job's id */
  job: string;
};

/** Types into a job's terminal. Result: {} */
export type JobInputParams = {
  /** the job's id */
  job: string;
  /** keys typed, as the terminal sends them (escapes included) */
  text: string;
};

/** The size a job's terminal is shown at (one size for every client: the last one told). Result: {} */
export type JobResizeParams = {
  /** the job's id */
  job: string;
  rows: number;
  cols: number;
};

/** Runs a job again (its output starts over). Result: {} */
export type RestartJobParams = {
  /** the job's id */
  job: string;
};

/** Changes settings. What may send things off this machine, decides what agents may do or names a program loom runs (bridges, pairing, speech to text, the agent program, the default mode, the editor, the notes vault) only from loom's window. Result: {} */
export type SetSettingsParams = {
  /** settings by their names in `settings`, with new values */
  changes: Record<string, unknown>;
};

/** Searches the notes vault. Result: {results: [{path, title, folder, snippet, modified}]} */
export type SearchNotesParams = {
  /** words, all of them in a note */
  query: string;
  /** results at most (30; 100 at most) */
  limit?: number;
};

/** Bytes kept by id (pictures), base64. Result: {data} */
export type BlobParams = {
  /** a blob id (an entry's `images`) */
  id: string;
};

/** Answers Scribe's question. Result: {} */
export type ScribeAnswerParams = {
  /** a `scribe` item */
  id: string;
  /** the answer */
  answer: string;
};

/** Decides on a change Scribe proposes. Result: {} */
export type ScribeDecideParams = {
  /** a `scribe` item */
  id: string;
  /** OK (true) or not */
  write: boolean;
};

/** Undoes what Scribe wrote. Result: {} */
export type ScribeUndoParams = {
  /** a `scribe` item */
  id: string;
};

/** Drops an item from Scribe's lists. Result: {} */
export type ScribeDropParams = {
  /** a `scribe` item */
  id: string;
};

/** Scribe changes a note it wrote as you say. Result: {} */
export type ScribeFixParams = {
  /** a `scribe` change it wrote */
  id: string;
  /** what's wrong or missing ("it's net, not gross") */
  said: string;
};

/** Tells Scribe why it was wrong. Result: {} */
export type ScribeTeachParams = {
  /** a `scribe` item */
  id: string;
  /** why not */
  said: string;
};

/** Keeps a rule Scribe proposes. Result: {} */
export type ScribeKeepRuleParams = {
  /** a `scribe` item */
  id: string;
  /** the rule */
  rule: string;
};

/** Everything Scribe wrote or was told no, newest first (`scribe_undo` takes a written one back). Result: {changes: [{id, kind: written|dropped, topic, reason, change, title, at, undone}]} */
export type ScribeHistoryParams = {
  /** 200; 2000 tops */
  limit?: number;
};

/** Forgets a rule Scribe learned. Result: {} */
export type ScribeForgetParams = {
  /** a `scribe` item */
  id: string;
};

/** A change Scribe wrote, seen: shown folded from then on. Result: {} */
export type ScribeSeenParams = {
  /** a `change` item of `scribe` (none: all) */
  id?: string;
};

/** Scribe reads what is left unread of a conversation, now ("Check now"). Result: {} */
export type ScribeCheckParams = {
  /** the conversation */
  session: string;
};

/** A file for an agent, saved in its folder under `<bridge>-files/` (a bridge's) or `web-files/` (dropped in a web page), never over another. Result: {path} */
export type SaveParams = {
  /** the agent's id */
  agent: string;
  /** the file's name */
  name: string;
  /** its bytes, base64 */
  data: string;
};

/** Speech to text with loom's settings (its key never leaves loom). Result: {text} */
export type TranscribeParams = {
  /** the recording, base64 */
  audio: string;
  /** its file name */
  name?: string;
  /** its type */
  mime?: string;
};

/** What the bridge says of itself (any object), shown in Settings. Result: {} */
export type BridgeStateParams = {

};

/** The bridge protocol, for bridges that still speak it (the remote one, for the phone app already shipped); its events: `bridge/<name>`. Result: {ok} or {error} */
export type BridgeParams = {
  /** a request of docs/bridges.md */
  method: string;
  /** its parameters */
  params?: Record<string, unknown>;
};

/** Starts the web page's server (this computer only) if it isn't, and a link to it with a one-time token (two minutes). The page is who opened the link: the window's rights, or the CLI's. Result: {url} */
export type WebOpenParams = {
  /** where to listen on 127.0.0.1 (else any free port), the first time */
  port?: number;
};

/** Stops the web page's server; every page let in is let go. Result: {} */
export type WebCloseParams = {

};

/** The notes vault's topics (Notes on, with a vault). Result: {vault, topics: [{name, path, folder, listens_for, apply: ask|auto, sync, enabled}]} */
export type TopicsParams = {

};

/** Switches a topic on or off. Result: {} */
export type TopicSetParams = {
  /** a topic's name */
  name: string;
  enabled: boolean;
};

/** A new topic, its file from loom's template or drafted from `about`. Result: {path} */
export type TopicNewParams = {
  /** its name */
  name: string;
  /** what it keeps, in a sentence: Claude drafts its file from it */
  about?: string;
};

/** The skills, agents and commands only loom's agents load (its Claude folder). Result: {folder, items: [{kind: skill|agent|command, name, description, enabled, shipped, path}]} */
export type ClaudeItemsParams = {

};

/** Switches one on or off (agents started or woken from now on). Result: {} */
export type ClaudeSetParams = {
  /** skill, agent or command */
  kind: string;
  name: string;
  enabled: boolean;
};

/** A new one, from loom's template. Result: {path} */
export type ClaudeNewParams = {
  /** skill, agent or command */
  kind: string;
  name: string;
};

/** Puts back loom's own version of one it ships. Result: {} */
export type ClaudeRestoreParams = {
  /** one loom ships */
  name: string;
};

/** Deletes a past conversation (Claude Code's file of it). It can't be undone. Result: {} */
export type DeleteConversationParams = {
  /** a past conversation (`past_conversations`) */
  session: string;
};

/** A folder's folders (hidden ones left out), to pick a project's folder. Result: {folder, parent, dirs: [name]} */
export type DirsListParams = {
  /** an absolute folder (none: home) */
  folder?: string;
};

/** Opens the file in the user's editor (the setting, else the desktop's), on this computer. Result: {} */
export type EditFileParams = {
  /** a file in a project, a topic's, or one of `claude_items`' */
  path: string;
};

/** A folder's entries, folders first (.git left out). Result: {entries: [{name, path, dir, size, modified}]} */
export type FilesListParams = {
  /** a folder in a project (absolute) */
  folder: string;
};

/** Finds a project's files by name (Ctrl+P), best first. Result: {files: [path relative to the project]} */
export type FilesFindParams = {
  /** a project's folder */
  project: string;
  /** letters of the path, in order */
  query: string;
  /** at most (50; 500 tops) */
  limit?: number;
};

/** A file's text (null: not text, or over 2 MB) and when it changed (ms), for `file_write`. Result: {text, size, modified} or {data, size} */
export type FileReadParams = {
  /** a file in a project */
  path: string;
  /** its bytes instead ({data}: base64, 10 MB at most) */
  bytes?: boolean;
};

/** Saves a file. Result: {modified} */
export type FileWriteParams = {
  /** a file in a project (new or not) */
  path: string;
  text: string;
  /** when it changed as read: a conflict if it changed since */
  modified?: number;
};

/** The project's git repositories and what changed in each (git's two letters: M  staged, ` M` not yet, ?? new). Result: {repos: [{path, name, branch, ahead, behind, changes: [{code, file}]}]} */
export type GitReposParams = {
  /** a project's folder */
  project: string;
};

/** A file's diff. Result: {diff} */
export type GitDiffParams = {
  /** one of `git_repos`' */
  repo: string;
  /** relative to it */
  file: string;
  /** the staged changes (else the ones not yet) */
  staged?: boolean;
};

/** Stages, unstages or throws away files' changes, or commits what is staged. Result: {} */
export type GitDoParams = {
  repo: string;
  /** stage, unstage, discard (back to the last commit: it can't be undone), commit */
  act: string;
  /** relative paths (not for commit) */
  files?: unknown[];
  /** commit's */
  message?: string;
};

/** Opens it on this computer (xdg-open). Result: {} */
export type OpenPathParams = {
  /** a file or folder in a project */
  path: string;
  /** app (its own app: the default), folder (its folder in the file manager) */
  how?: string;
};

/** Moves it to the desktop's trash (gio trash). Result: {} */
export type TrashFileParams = {
  /** a file or folder in a project (not the project) */
  path: string;
};

/** One commit: who, when, its message, the files it changed and its diff (git show). Result: {text} */
export type GitShowParams = {
  repo: string;
  /** a commit's (`git_log`) */
  hash: string;
};

/** The newest commits. Result: {commits: [{graph, hash, refs, subject, author, when, parents}]} */
export type GitLogParams = {
  repo: string;
  /** 200; 2000 tops */
  limit?: number;
  /** every branch, with the graph drawn before each line */
  graph?: boolean;
  /** every branch (no graph drawn) */
  all?: boolean;
  /** the newest ones left out: the next page */
  skip?: number;
};

/** A project's board, `.loom/board.md` in its folder (the Obsidian Kanban plugin's format): lanes and their cards, dates local to the minute. Agents use their loom tools for their own project's. Result: {project, file, lanes: [{title, cards: [{id, title, body, done, created, started, finished, by}]}]} */
export type BoardParams = {
  /** a project's folder */
  project: string;
};

/** A new card at the end of a lane. Result: {card} */
export type BoardAddParams = {
  project: string;
  title: string;
  /** its description */
  body?: string;
  /** a lane's title (none: the first) */
  lane?: string;
};

/** A card to a lane: started when it enters Doing, done (checked) when it enters Done. Result: {} */
export type BoardMoveParams = {
  project: string;
  card: number;
  lane: string;
  /** the card it goes before (none: the end) */
  before?: number;
};

/** A card's title or description changed. Result: {} */
export type BoardEditParams = {
  project: string;
  card: number;
  title?: string;
  /** its whole description */
  body?: string;
  /** added below its description */
  note?: string;
};

/** Puts an agent on a card: a new one, or `agent` (after its turn, if it works). The card's title and description are its message, the card goes to Doing, and the agent's work is logged on it. Result: {agent} */
export type BoardWorkParams = {
  project: string;
  card: number;
  /** one of the project's agents to give it to (none: a new agent) */
  agent?: string;
};

/** The same card tried by 2 or 3 new agents at once, each in a worktree of its own (branches card-<id>-try-<n>), to compare and keep one: the card goes to Doing, each logs its work on it. Result: {agents} */
export type BoardTriesParams = {
  project: string;
  card: number;
  /** 2 (default) or 3 */
  tries?: number;
};

/** Done's cards moved to .loom/board-archive.md (a board of its own, newest first); new cards never take their ids. Result: {archived} */
export type BoardArchiveParams = {
  project: string;
};

/** A card taken off the board. Result: {} */
export type BoardRemoveParams = {
  project: string;
  card: number;
};

/** An ask answered: a file filled in (the agent goes on), or one seen (it goes). Result: {} */
export type AskDoneParams = {
  /** an `asks` item */
  id: string;
};

/** A file the user won't fill in: the agent hears they cancelled; the ask goes. Result: {} */
export type AskCancelParams = {
  /** an `edit` item of `asks` */
  id: string;
};

/** Opens an ask's file in the user's editor (the setting, else the desktop's), on this computer. Result: {} */
export type AskOpenParams = {
  /** an `asks` item with a file */
  id: string;
};

/** loomd: a Notes chat open (an agent working in the vault): its conversation is `conversation/<agent>`. Result: {agent} */
export type NotesOpenParams = {
  /** a past chat (`notes_chats`); none: a new one */
  session?: string;
  /** a new chat about this topic (`topics`), its notes in reach */
  topic?: string;
};

/** loomd: a Notes chat closed (it stays among the past ones). Result: {} */
export type NotesCloseParams = {
  /** the chat's agent */
  agent: string;
};

/** An agent's loom tools (its MCP server), as the agent loom found the caller to be. Result: the tool's answer */
export type ToolParams = {
  /** a loom tool's request (run_job, job_output, open_file, …) */
  name: string;
  /** its parameters */
  params?: Record<string, unknown>;
};

/** Code search (loom_find): by meaning when Settings has it on, else by words. loomd keeps one index per folder, shared by every agent and the window. Result: {found: [{path, line, head, doc, also, peek}], note, used: [{path, line, text}]} */
export type FindCodeParams = {
  /** what to find, in words or a name */
  query: string;
  /** the folder to search, absolute (an agent: its own folder, or one in its project) */
  root: string;
  /** people: the project whose concept cards count too (default: root) */
  project?: string;
  /** how many places (default 10, at most 25) */
  limit?: number;
};

